        cylindrical_to_cartesian=cylindrical_to_cartesian, theme=theme,
        xscale=xscale, yscale=yscale, zscale=zscale, xshift=xshift,
        yshift=yshift, zshift=zshift, xlabel=xlabel, ylabel=ylabel,
