        xlabel=xlabel, ylabel=ylabel, clabel=clabel, title=title,
        subplot_titles=subplot_titles, subplot_xlabels=subplot_xlabels,
        subplot_ylabels=subplot_ylabels, logx=logx, logy=logy, logz=logz,
