        save=bool(output_paths),
        saveas=(None if not output_paths else
            output_paths[0] if len(output_paths) == 1 else output_paths),
        dpi=dpi, show=False)

    if subplots:
      start_axes += d.num_comps
    # end

  # end

  if show and not (saveframes or ds.batch):
    plt.show()
  # end
  else:
